def replace_fillers(n, s):
    i = 0
    result = ""
    while i < n:
        if s[i:i+3] == "ogo":
            result += "***"
            i += 3
            while i < n and s[i:i+2] == "go":
                i += 2
        else:
            result += s[i]
            i += 1
    return result

n = int(input())
s = input()
print(replace_fillers(n, s))
